11	import 'package:cerne/core/network/access_token_provider.dart';
12	import 'package:cerne/core/network/retry_interceptor.dart';
13	import 'package:cerne/core/network/url_builder.dart';
14	import 'package:cerne/features/entries/presentation/cubit/meus_registros_cubit.dart';
15	import 'package:cerne/features/entries/presentation/cubit/meus_registros_state.dart';
16	
17	import '../../support/fake_path_provider_platform.dart';
18	
19	/// Same shape as `capture_flow_e2e_test.dart`'s own fake — only the
20	/// transport boundary is faked, everything above it (URL building, both
21	/// real interceptors, `ApiClient`'s mapping) and below it (real `hive_ce`
22	/// write-through) is the genuine production wiring. [queueErrorResponse]
23	/// additionally lets a test simulate a retryable backend code (e.g.
24	/// `NETWORK_OFFLINE`) the same way `network_pipeline_integration_test.dart`
25	/// does — a JSON body carrying `code`, not a thrown `DioException` — since
26	/// `dioErrorCodeOf` reads `data['code']` before ever looking at the
27	/// response's own HTTP status.
28	class _FakeHttpClientAdapter implements HttpClientAdapter {
29	  final List<RequestOptions> requests = [];
30	  final List<({int statusCode, Map<String, dynamic> body})> _queue = [];
31	
32	  void queueJsonResponse(int statusCode, Map<String, dynamic> body) {
33	    _queue.add((statusCode: statusCode, body: body));
34	  }
35	
36	  void queueErrorResponse(String code, String message) {
37	    queueJsonResponse(503, {
38	      'code': code,
39	      'message': message,
40	      'retryable': true,
41	    });
42	  }
43	
44	  @override
45	  Future<ResponseBody> fetch(
46	    RequestOptions options,
47	    Stream<Uint8List>? requestStream,
48	    Future<void>? cancelFuture,
49	  ) async {
50	    requests.add(options);
51	    if (_queue.isEmpty) {
52	      throw StateError(
53	        'No queued response for ${options.method} ${options.path}',
54	      );
55	    }
56	    final next = _queue.removeAt(0);
57	    return ResponseBody.fromString(
58	      jsonEncode(next.body),
59	      next.statusCode,
60	      headers: {
61	        Headers.contentTypeHeader: [Headers.jsonContentType],
62	      },
63	    );
64	  }
65	
66	  @override
67	  void close({bool force = false}) {}
68	}
69	
70	Map<String, dynamic> _entryJson({
71	  required String id,
72	  required String content,
73	  required String source,
74	  required String occurredAt,
75	}) => {
76	  'id': id,
77	  'content': content,
78	  'source': source,
79	  'chatMessageId': null,
80	  'occurredAt': occurredAt,
81	  'serverRevision': 1,
82	  'createdAt': occurredAt,
83	  'updatedAt': occurredAt,
84	};
85	
86	/// End-to-end coverage for spec-4-1's `list()` path — the counterpart
87	/// `capture_flow_e2e_test.dart` already proves for `create()`. Driven
88	/// directly against `MeusRegistrosCubit`'s own public API
89	/// (`loadFirstPage`/`loadMore`), the exact `lazySingleton` instance
90	/// `MeusRegistrosScreen` resolves through `sl`, wired to the real
91	/// `EntriesRepositoryImpl` -> `EntriesRemoteDataSource` -> `ApiClient` ->
92	/// `Dio` (both real interceptors attached) -> a real `entries` Hive box.
93	///
94	/// This complements rather than duplicates existing coverage:
