274	/// already-held id *and* a duplicate within [entries] itself, since a
275	/// local copy of [seenIds] accumulates as entries are walked (the caller's
276	/// own set, if any, is never mutated).
277	List<Entry> _dedupedById(List<Entry> entries, {Set<String>? seenIds}) {
278	  final seen = {...?seenIds};
279	  return [
280	    for (final entry in entries)
281	      if (seen.add(entry.id)) entry,
282	  ];
283	}
